import {mkdir,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import {rasterBuilder,rasterSVG} from './program.js';import {createReleaseManifest,inspectResource} from 'galbox-sdk/release';import {encodeWire} from 'galbox-sdk/wire';
const sha=createHash('sha256').update(rasterSVG).digest('hex');for(const kind of ['film','accumulate']as const){const root=`tests/player-app/public/raster-${kind}`;await mkdir(root,{recursive:true});const program=rasterBuilder(kind,sha).build(),resources=await Promise.all(program.assets.map(a=>inspectResource(a,new TextEncoder().encode(rasterSVG),bytes=>new TextDecoder().decode(bytes)))),release=await createReleaseManifest({program,series:'1',resources},{async sha256(text){return createHash('sha256').update(text).digest('hex');}});await writeFile(root+'/pattern.svg',rasterSVG);await writeFile(root+'/program.json',JSON.stringify(program));await writeFile(root+'/release.pb',encodeWire('ReleaseManifest',release));}
